################################################################################ This script outputs the site name, url and last modified date for each # SharePoint site in the list of site collections specified in tab separated# format. This script is backwards compatible with SharePoint 2007. ############################################################################### For SharePoint 2007 compatibility[System.Reflection.Assembly]::LoadWithPartialName("Microsoft.SharePoint")# Specifies path for text file containing SharePoint site collection urls$SitesList = Get-Content -Path "C:\Solutions\SitesList.txt"#Write the Header to "Tab Separated Text File""Site Name`t  URL `t Last Modified Date" | Out-File "LastModifiedDateReport.csv"# Runs for every site collectionforeach($Siteurl in $Siteslist){    # Output site collection name    Write-Output ""    Write-Output "Working on site collection $Siteurl"    $Site = New-Object Microsoft.SharePoint.SPSite($SiteUrl)    # Iterate through all Webs    foreach ($web in $Site.AllWebs)    {        #Write the Header to "Tab Separated Text File"        "$($web.title) `t $($web.URL) `t $($web.lastitemmodifieddate) " | Out-File "LastModifiedDateReport.csv" -append          $web.dispose()    }}Write-Output "" Write-Output "Script Execution finished"###################################################################### End of Script#####################################################################